function queryRuleMatches(rule,query,day,source){
  const text=String(query||'').trim().toLocaleLowerCase('fr');
  if(!text||/["():*]/.test(text)||/(^|\s)(and|or|not)(\s|$)/i.test(text))return false;
  if(!rule.active||(source!=='all'&&rule.source!=='all'&&rule.source!==source)||(rule.start&&day<rule.start)||(rule.end&&day>rule.end))return false;
  const conditions=Array.isArray(rule.conditions)?rule.conditions:(rule.phrases?[rule]:[]);
  if(!conditions.length)return true;
  return conditions.some(condition=>{
    const phrases=String(condition.phrases||'').split(';').map(value=>value.trim().toLocaleLowerCase('fr')).filter(Boolean);
    const atStart=phrase=>text===phrase||text.startsWith(phrase+' '),atEnd=phrase=>text===phrase||text.endsWith(' '+phrase);
    if(condition.conditionType==='action')return phrases.some(phrase=>atStart(phrase)||atEnd(phrase));
    if(condition.conditionType==='advanced')return phrases.some(phrase=>(condition.matchExact&&text===phrase)||(condition.matchStart&&atStart(phrase))||(condition.matchEnd&&atEnd(phrase)));
    return phrases.includes(text);
  });
}
