function normalDetailPanel(site,doc){const path=normalFolderPath(normalDocuments(site),doc.parent).map(item=>item.name).join(' / ')||'Documents';return `<aside class="panel normal-details" aria-label="Détails de ${esc(doc.name)}"><div class="panel-head">Détails <button class="plain" data-normal="details-close" aria-label="Fermer les détails">×</button></div><div class="panel-body"><h3>${esc(doc.name)}</h3><p>${doc.kind==='folder'?'Dossier':'Fichier'} · ${doc.kind==='folder'?'—':esc(size(doc.size))}</p><dl><dt>Emplacement</dt><dd>${esc(path)}</dd><dt>Modifié</dt><dd>${esc(doc.modified||'—')}</dd><dt>Accès directs fictifs</dt><dd>${(doc.shares||[]).length}</dd>${doc.kind!=='folder'?`<dt>Versions locales précédentes</dt><dd>${normalVisibleVersions(doc).length}</dd>`:''}</dl>${demoViewerDetails(site,doc)}${normalTermFields(site,doc)}<button class="btn" data-normal="select" data-value="${esc(doc.id)}">Ouvrir</button>${canEdit()?` <button class="btn" data-normal="share" data-value="${esc(doc.id)}">Partager</button>`:''}</div></aside>`}
function normalBatchDestinations(docs,ids){const sources=ids.map(id=>docs.find(item=>item.id===id&&!item.deleted));if(sources.some(item=>!item))return [];const excluded=new Set();try{for(const source of sources){excluded.add(source.id);if(source.kind==='folder')for(const item of DocumentTree.descendants(normalTreeItems(docs),source.id))excluded.add(item.id)}}catch{return []}return docs.filter(item=>item.kind==='folder'&&!item.deleted&&!excluded.has(item.id)).map(item=>({id:item.id,label:normalFolderPath(docs,item.id).map(part=>part.name).join(' / ')}))}
function normalDraftKey(siteId,docId){return JSON.stringify([siteId,docId])}
