function normalVersionExpired(version,now=Date.now()){const expiry=Date.parse(version.expiresAt||'');return Number.isFinite(expiry)&&expiry<=now}
function normalVisibleVersions(doc){return Array.isArray(doc.versions)?doc.versions.filter(version=>!normalVersionExpired(version)):[]}
function trimNormalVersions(doc,site,now=Date.now()){if(!Array.isArray(doc.versions))return;doc.versions=doc.versions.filter(version=>!normalVersionExpired(version,now));const policy=site.documentVersionPolicy;if(policy?.mode==='automatic'){const selected=new Set(),buckets=new Map();doc.versions.forEach((version,index)=>{const time=Date.parse(version.date||''),age=now-time;if(!Number.isFinite(time)||age<=30*86400000){selected.add(index);return}const date=new Date(time);let key;if(age<=60*86400000)key='h:'+date.toISOString().slice(0,13);else if(age<=180*86400000)key='d:'+date.toISOString().slice(0,10);else{const day=Date.UTC(date.getUTCFullYear(),date.getUTCMonth(),date.getUTCDate()),monday=day-((date.getUTCDay()+6)%7)*86400000;key='w:'+monday}const previous=buckets.get(key);if(!previous||time<previous.time)buckets.set(key,{index,time})});for(const item of buckets.values())selected.add(item.index);doc.versions=doc.versions.filter((_,index)=>selected.has(index));if(doc.versions.length>499)doc.versions.splice(0,doc.versions.length-499);return}const limit=policy?.mode==='manual'?policy.count:null;if(Number.isInteger(limit)&&limit>=100&&limit<=50000){const excess=doc.versions.length-(limit-1);if(excess>0)doc.versions.splice(0,excess)}}
function normalSnapshot(doc,site){const now=new Date(),days=site.documentVersionPolicy?.mode==='manual'?site.documentVersionPolicy.expiryDays:0,expiresAt=Number.isInteger(days)&&days>=30&&days<=36500?new Date(now.getTime()+days*86400000).toISOString():'';return {id:crypto.randomUUID(),date:now.toISOString(),...(expiresAt?{expiresAt}:{}),customFields:structuredClone(doc.customFields||{}),content:doc.content||'',dataUrl:doc.dataUrl||'',mime:doc.mime||'',size:doc.size||0,modified:doc.modified||''}}
function normalTextFile(doc){return !doc.dataUrl||/^text\//i.test(doc.mime||'')||/\.(txt|md|csv)$/i.test(doc.name)}
function normalPreview(doc){if(/^data:image\/(png|jpeg|gif|webp);base64,/i.test(doc.dataUrl||''))return `<img class="preview-image" src="${esc(doc.dataUrl)}" alt="${esc(doc.name)}">`;if(/^data:application\/pdf;base64,/i.test(doc.dataUrl||'')&&normalLinkPermission()==='NoDownload')return '<p>Aperçu PDF indisponible dans ce mode de démonstration.</p>';if(/^data:application\/pdf;base64,/i.test(doc.dataUrl||''))return `<iframe class="preview-pdf" title="Aperçu PDF" sandbox src="${esc(doc.dataUrl)}"></iframe>`;if(/\.(docx|xlsx|pptx)$/i.test(doc.name)&&doc.dataUrl)return '<p class="muted">Aperçu textuel local : la mise en page et certains éléments ne sont pas reproduits.</p><div class="preview-text" id="normal-office-preview" role="status">Chargement de l’aperçu…</div>';return '<p class="muted">Aperçu indisponible ; téléchargez le fichier pour l’ouvrir.</p>'}
function bindNormalOfficePreview(site,doc){const target=$('#normal-office-preview');if(!target||!doc)return;const id=doc.id,data=doc.dataUrl,siteId=site.id;if(typeof OfficePreview==='undefined'){target.textContent='Aperçu indisponible ; téléchargez le fichier.';return}OfficePreview.extract(data,doc.name.split('.').pop()).then(text=>{const current=db.sites.find(item=>item.id===siteId&&!item.deleted),item=current&&normalDocuments(current).find(entry=>entry.id===id&&!entry.deleted);if(target.isConnected&&state.page==='Demo site'&&state.normalSiteId===siteId&&state.normalDocumentId===id&&item?.dataUrl===data)target.textContent=text||'Ce document est vide.'}).catch(()=>{if(target.isConnected&&state.page==='Demo site'&&state.normalSiteId===siteId&&state.normalDocumentId===id)target.textContent='Aperçu indisponible ; téléchargez le fichier.'})}
function normalVersionHistory(doc){const versions=normalVisibleVersions(doc);if(!versions.length)return '';return `<details class="normal-history"><summary>Historique des versions (${versions.length})</summary>${versions.reverse().map(version=>`<details><summary>${esc(new Date(version.date).toLocaleString('fr-FR'))}</summary>${normalTextFile({...doc,...version})?`<pre>${esc(version.content||'')}</pre>`:'<p>Version de fichier conservée localement.</p>'}${!['NoDownload','Denied'].includes(normalLinkPermission())?`<button type="button" class="btn" data-normal="download-version" data-value="${esc(version.id)}">Télécharger cette version</button>`:''}${canEdit()?`<button type="button" class="btn" data-normal="restore-version" data-value="${esc(version.id)}">Restaurer cette version</button>`:''}</details>`).join('')}</details>`}
function normalDownload(doc){if(demoScopeReauthPerson()){render();return}if(!doc||doc.deleted||doc.kind==='folder'||['NoDownload','Denied'].includes(normalLinkPermission()))return;const data=typeof doc.dataUrl==='string'&&doc.dataUrl.startsWith('data:')?doc.dataUrl:'',url=data||URL.createObjectURL(new Blob([doc.content||''],{type:'text/plain;charset=utf-8'})),anchor=document.createElement('a');anchor.href=url;anchor.download=doc.name;anchor.click();if(!data)setTimeout(()=>URL.revokeObjectURL(url),1000)}
async function normalImportFiles(input){
  const files=Array.from(input.files||[]),siteId=state.normalSiteId,folder=state.normalFolder||null;if(!files.length)return;
  if(!canEdit()||state.page!=='Demo site'||state.normalSiteTab!=='documents'){input.value='';return}
  try{
    const site=db.sites.find(item=>item.id===siteId&&!item.deleted);if(!site)throw Error('Le site n’est plus disponible.');
    const baseline=JSON.stringify(normalDocuments(site)),storage=localStorage.getItem(key),next=structuredClone(normalDocuments(site)),names=new Set(),candidates=[];
    for(const file of files){let parent=folder;const name=String(file.name||''),segments=String(file.webkitRelativePath||'').split('/').filter(Boolean).slice(0,-1);if(!name.trim()||name.length>255||/[\\/]/.test(name)||name==='.'||name==='..')throw Error('Nom de fichier invalide.');for(const segment of segments){if(!segment.trim()||segment==='.'||segment==='..'||segment.length>255||/[\\/]/.test(segment))throw Error('Nom de dossier invalide.');if(names.has(JSON.stringify([parent,segment.toLocaleLowerCase('fr')])))throw Error('Un fichier chargé porte déjà le nom d’un dossier.');let child=next.find(item=>!item.deleted&&(item.parent||null)===parent&&item.name.toLocaleLowerCase('fr')===segment.toLocaleLowerCase('fr'));if(child&&child.kind!=='folder')throw Error('Un fichier porte déjà le nom d’un dossier chargé.');if(!child){child={id:crypto.randomUUID(),name:segment,kind:'folder',parent,modified:new Date().toISOString().slice(0,10),deleted:false};next.push(child)}parent=child.id}const keyName=JSON.stringify([parent,name.toLocaleLowerCase('fr')]);if(names.has(keyName))throw Error('Les fichiers chargés doivent avoir des noms distincts dans chaque dossier.');names.add(keyName);const existing=next.find(item=>!item.deleted&&(item.parent||null)===parent&&item.name.toLocaleLowerCase('fr')===name.toLocaleLowerCase('fr'));if(existing?.kind==='folder')throw Error('Un dossier porte déjà ce nom.');candidates.push({file,name,parent,existingId:existing?.id||''})}
    const replacing=candidates.filter(item=>item.existingId);if(replacing.length&&!confirm(`Remplacer ${replacing.length} fichier(s) existant(s) par les fichiers chargés ? La version enregistrée actuelle sera conservée et les brouillons non enregistrés seront abandonnés.`))return;
    const draftBaseline=normalReplacementDrafts(siteId,replacing),prepared=[];for(const candidate of candidates){const {file,name,parent,existingId}=candidate,encoded=await dataUrl(file),mime=String(file.type||''),content=/^text\//i.test(mime)||/\.(txt|md|csv)$/i.test(name)?await file.text():'';prepared.push({existingId,id:existingId||crypto.randomUUID(),name,kind:'file',parent,content,dataUrl:encoded,mime,size:Number(file.size)||0,modified:new Date().toISOString().slice(0,10),deleted:false})}
    const current=db.sites.find(item=>item.id===siteId&&!item.deleted);if(!current||state.page!=='Demo site'||state.normalSiteId!==siteId||state.normalSiteTab!=='documents'||(state.normalFolder||null)!==folder||!canEdit()||JSON.stringify(normalDocuments(current))!==baseline||localStorage.getItem(key)!==storage||normalReplacementDrafts(siteId,replacing)!==draftBaseline)throw Error('Le site, le dossier ou un brouillon a changé pendant le chargement. Réessayez.');
    for(const uploaded of prepared){if(uploaded.existingId){const target=next.find(item=>item.id===uploaded.existingId&&!item.deleted&&item.kind!=='folder');if(!target)throw Error('Le fichier n’est plus disponible.');target.versions||=[];target.versions.push(normalSnapshot(target,current));Object.assign(target,{content:uploaded.content,dataUrl:uploaded.dataUrl,mime:uploaded.mime,size:uploaded.size,modified:uploaded.modified});trimNormalVersions(target,current)}else{const {existingId,...item}=uploaded;next.push(item)}}
    if(!updateNormalDocuments(current,items=>{if(folder&&!items.some(item=>item.id===folder&&item.kind==='folder'&&!item.deleted))throw Error('Le dossier n’est plus disponible.');items.length=0;for(const item of next)items.push(item)}))return;
    for(const item of replacing)if(state.normalDrafts)delete state.normalDrafts[normalDraftKey(siteId,item.existingId)];render();notice(replacing.length?'Fichiers chargés et versions locales conservées.':'Fichiers chargés localement.');
  }catch(error){notice(error?.message||'Chargement local impossible.')}finally{input.value=''}
}
function sharePermissionDefault(draft){return ['Read','Edit','NoDownload'].includes(draft?.permission)?draft.permission:db.adminSharing?.permission==='read'?'Read':'Edit'}
function normalAllowsAnyone(site){return Math.max(Number(db.adminSharing?.sharepoint??1),Number(site.sharing??1))===0}
function normalNewLinkSettings(site,doc){const policy=db.adminSharing||{},configured=['specific','existing','organization','anyone'].includes(site.defaultLinkType)?site.defaultLinkType:policy.linkType,type=['specific','existing','organization','anyone'].includes(configured)?configured:'specific',audience=type==='anyone'&&(!normalAllowsAnyone(site)||!demoActorCanShareAnyone())?'organization':type,created=demoDate(),permission=['read','edit'].includes(site.defaultLinkPermission)?site.defaultLinkPermission:policy.permission;return {audience,permission:permission==='read'||(audience==='anyone'&&demoAnyoneReadOnly(doc))?'Read':'Edit',created,expires:audience==='anyone'?demoLinkMaxExpiry(created,site):''}}
function normalLinkSettings(site,doc,linkId=''){if(linkId)return (Array.isArray(doc.normalLinks)?doc.normalLinks:[]).find(link=>link.id===linkId)||null;return doc.normalLinkSettings||{audience:'specific',permission:'Edit',created:'',expires:''}}
function localExistingAccess(site,doc,docs,person){if(!demoGuestAccessAllowed(site,person,'existing'))return '';const rank={NoDownload:0,Read:1,Edit:2},levels=[];if(site.owner===person)levels.push('Edit');for(const member of Array.isArray(site.members)?site.members:[])if(principalIncludes(member.name,person))levels.push(/visiteur/i.test(member.role||'')?'Read':'Edit');const seen=new Set();let current=doc;while(current&&!seen.has(current.id)){seen.add(current.id);for(const share of Array.isArray(current.shares)?current.shares:[])if(principalIncludes(share.person,person)&&Object.hasOwn(rank,share.permission))levels.push(share.permission);for(const link of Array.isArray(current.normalLinks)?current.normalLinks:[])if(link.audience==='specific'&&Array.isArray(link.recipients)&&link.recipients.some(recipient=>principalIncludes(recipient,person))&&Object.hasOwn(rank,link.permission))levels.push(link.permission);current=current.parent?docs.find(entry=>entry.id===current.parent&&entry.kind==='folder'&&!entry.deleted):null}return levels.length?levels.reduce((best,value)=>rank[value]>rank[best]?value:best):''}
function normalExistingAccess(site,doc,person){return localExistingAccess(site,doc,normalDocuments(site),person)}
